import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { uv, vec3, mix, color, smoothstep, sin, fract, texture, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, SRGBColorSpace } = ctx.THREE;

  const group = new Group();
  group.userData.handlers = {};
  group.userData.timelines = [];

  const ourMaterials = [];
  const ourGeometries = [];

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {};

  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const surface = colors.surface ?? '#0b0b10';
  const accent = colors.accent ?? '#ff2a38';

  // Backdrop: engineered vertical gradient + subtle grain
  const bgGeo = new PlaneGeometry(7, 6);
  const surfaceNode = color(surface);
  const inkNode = color(ink);
  const gradientT = smoothstep(0.0, 1.0, uv().y);
  const gradBase = mix(surfaceNode, inkNode, gradientT);

  const noiseUv = uv().mul(512.0);
  const hash = fract(
    sin(
      noiseUv.x.mul(127.1).add(noiseUv.y.mul(311.7))
    ).mul(43758.5453)
  );
  const grain = vec3(hash.sub(0.5).mul(0.05));
  const bgColor = clamp(gradBase.add(grain), 0.0, 1.0);

  const bgMat = new MeshBasicNodeMaterial({ side: ctx.THREE.DoubleSide });
  bgMat.colorNode = bgColor;
  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.z = -2.5;
  group.add(bgMesh);

  ourGeometries.push(bgGeo);
  ourMaterials.push(bgMat);

  // Textured card plane
  const cardW = 2.0;
  const cardH = 1.25;
  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({ side: ctx.THREE.DoubleSide, transparent: false });
  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  ourGeometries.push(cardGeo);
  ourMaterials.push(cardMat);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (!tex) return;
      tex.colorSpace = SRGBColorSpace;
      tex.flipY = false;
      cardMat.colorNode = texture(tex).rgb;
      cardMat.needsUpdate = true;
    }).catch(() => {});
  }

  // Accent bar (signal red, <=10% of card area)
  const accentGeo = new PlaneGeometry(0.5, 0.04);
  const accentMat = new MeshBasicNodeMaterial({ color: accent, transparent: false });
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-cardW / 2 + 0.3, -cardH / 2 + 0.12, 0.01);
  group.add(accentMesh);

  ourGeometries.push(accentGeo);
  ourMaterials.push(accentMat);

  // Text content from spec
  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    if (!item?.text) continue;
    const fontSize = item.typography?.fontSize ?? 39;
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: paper,
      align: 'center',
    });
    if (textObj) {
      textObj.position.set(0, 0.08, 0.03);
      group.add(textObj);
    }
  }

  // Cinematic primitives
  for (const primitive of (config.cinematicPrimitives ?? [])) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(group, primitive.params);
      if (result?.timeline) {
        group.userData.timelines.push(result.timeline);
      }
    }
  }

  group.userData.cleanup = () => {
    group.userData.timelines.forEach((tl) => {
      try { tl.kill(); } catch (e) {}
    });

    ourMaterials.forEach((mat) => {
      try {
        if (mat.map) mat.map.dispose();
        mat.dispose();
      } catch (e) {}
    });

    ourGeometries.forEach((geo) => {
      try { geo.dispose(); } catch (e) {}
    });

    group.traverse((obj) => {
      if (obj.geometry && !ourGeometries.includes(obj.geometry)) {
        try { obj.geometry.dispose(); } catch (e) {}
      }
      if (obj.material && !ourMaterials.includes(obj.material)) {
        try { obj.material.dispose(); } catch (e) {}
      }
    });
  };

  return group;
}
